def choose_move(observation):
    pos = observation.get("self_position") or observation.get("position") or {}
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    grid_w = observation.get("grid_width") or observation.get("width") or 0
    grid_h = observation.get("grid_height") or observation.get("height") or 0

    resources = observation.get("resources") or []
    obstacles = set(observation.get("obstacles") or [])

    opp = observation.get("opponent_position") or {}

    # Try to move toward the nearest resource if available
    best_dx, best_dy = 0, 0
    best_dist = 10**9

    def consider(rx, ry):
        nonlocal best_dx, best_dy, best_dist
        if rx is None or ry is None:
            return
        d = abs(rx - x) + abs(ry - y)
        if d < best_dist:
            best_dist = d
            best_dx = rx - x
            best_dy = ry - y
            # clamp to -1..1 for each axis
            if best_dx != 0:
                best_dx = int(best_dx / abs(best_dx))
            if best_dy != 0:
                best_dy = int(best_dy / abs(best_dy))

    for r in resources:
        rx = r.get("x")
        ry = r.get("y")
        consider(rx, ry)

    if best_dist < 10**9:
        nx, ny = x + best_dx, y + best_dy
        if 0 <= nx < grid_w and 0 <= ny < grid_h and (nx, ny) not in obstacles:
            return [best_dx, best_dy]

    # If no resource target, try to move away from opponent or towards center
    if opp:
        ox = opp.get("x", x)
        oy = opp.get("y", y)
        dx = x - ox
        dy = y - oy
        if dx != 0 or dy != 0:
            move_x = int(dx / abs(dx)) if dx != 0 else 0
            move_y = int(dy / abs(dy)) if dy != 0 else 0
            nx, ny = x + move_x, y + move_y
            if 0 <= nx < grid_w and 0 <= ny < grid_h and (nx, ny) not in obstacles:
                return [move_x, move_y]

    # Otherwise, attempt to stay still if not blocked
    if (x, y) not in obstacles:
        return [0, 0]

    # Fallback: try any adjacent free cell deterministically (up, left, right, down)
    for dx, dy in [(0, -1), (-1, 0), (1, 0), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < grid_w and 0 <= ny < grid_h and (nx, ny) not in obstacles:
            return [dx, dy]

    # If completely blocked, stay
    return [0, 0]
